<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ArrowDownToLine, CircleHelp, FlaskConical, Play, Plus, Timer, X } from '@lucide/vue'
import { apiError, learningApi } from '../api/client'
import SectionHeading from '../components/SectionHeading.vue'
import { experimentCsv, experimentJson, type ExperimentExportRun } from '../domain/experimentExport'
interface Answer { mode: string; answer: string; latencyMs: number; error?: string; prompt?: string; triples?: Array<{ subject: string; predicate: string; object: string; score?: number }>; provenance?: Record<string, unknown>; grounding?: { strategyVersion: string; status: string; candidates: unknown[]; selectedIds: string[]; selectedEvidence: unknown[]; selectionMs: number; answerMs: number; modelCallCount: number }; experimentType?: string; modelVariant?: string; resultKey?: string }
interface Scores { rougeL?: number; bleu4?: number; bleuOrder?: number; entityRecall?: number }
interface Run { id: string; question: string; createdAt: string; results: Answer[]; ratings: Record<string, number>; evaluation?: { source?: string; experimentType?: string; metricsByMode?: Record<string, Scores>; note?: string } }
const question = ref('数据流图中，加工的命名应采用什么形式？')
const referenceAnswer = ref('加工命名的语法结构必须采用动词+宾语的动宾短语形式，如校验权限、生成报表')
const expectedEntityInputs = ref(['动宾短语', '', ''])
const experimentType = ref<'METHODS' | 'QWEN_MATRIX'>('METHODS')
const rankedPromptVersion = 'ranked-grounded-v3'
const includeAblations = ref(false)
const taskId = computed(() => Number(new URLSearchParams(window.location.search).get('taskId')) || undefined)
const running = ref(false), error = ref(''), latest = ref<Run | null>(null), history = ref<Run[]>([])
const executionPhase = ref<'idle' | 'running' | 'complete'>('idle')
const executionStartedAt = ref<number | null>(null)
const executionElapsed = ref(0)
let executionTimer: ReturnType<typeof setInterval> | null = null
const expectedConditions = computed(() => experimentType.value === 'QWEN_MATRIX' ? 6 : 3 + (includeAblations.value ? 4 : 0))
const executionStatusText = computed(() => executionPhase.value === 'running' ? '服务端正在并行执行并统一校验各条件' : executionPhase.value === 'complete' ? `已返回 ${latest.value?.results.length || 0} 个实际条件` : '等待运行')
const modeNames: Record<string, string> = { ABLATION_SORTED_SCORED: '消融基线：排序且评分', ABLATION_WITHOUT_SCORE: '消融：不评分', ABLATION_WITHOUT_SORT: '消融：不排序', ABLATION_WITHOUT_SORT_AND_SCORE: '消融：不排序且不评分', DIRECT: '大模型直答', TRIPLES: '三元组增强', RANKED: '排序评分 + 原始提示词', QWEN_BASE_DIRECT: 'Qwen 基座 · DIRECT', QWEN_BASE_TRIPLES: 'Qwen 基座 · TRIPLES', QWEN_BASE_RANKED: 'Qwen 基座 · RANKED', QWEN_LORA_DIRECT: 'Qwen LoRA · DIRECT', QWEN_LORA_TRIPLES: 'Qwen LoRA · TRIPLES', QWEN_LORA_RANKED: 'Qwen LoRA · RANKED', NO_SORT: '消融：不排序', NO_SCORE: '消融：不评分', NO_SORT_NO_SCORE: '消融：不排序且不评分', WITHOUT_SORT: '消融：不排序', WITHOUT_SCORE: '消融：不评分', WITHOUT_SORT_AND_SCORE: '消融：不排序且不评分' }
const summary = computed(() => {
  const groups = new Map<string, { key: string; label: string; count: number; failed: number; times: number[]; ratings: number[] }>()
  for (const run of history.value.filter(r => r.evaluation?.source === 'SERVER_AI_SERVICE')) for (const result of run.results) {
    if (result.mode === 'RANKED' && result.provenance?.systemPromptVersion !== rankedPromptVersion) continue
    const key = `${run.evaluation?.experimentType || 'METHODS'}:${result.resultKey || result.mode}`
    const entry = groups.get(key) || { key, label: modeNames[result.resultKey || result.mode] || result.resultKey || result.mode, count: 0, failed: 0, times: [], ratings: [] }
    entry.count++; if (result.error) entry.failed++; else entry.times.push(result.latencyMs)
    if (run.ratings[result.resultKey || result.mode]) entry.ratings.push(run.ratings[result.resultKey || result.mode]!)
    groups.set(key, entry)
  }
  return [...groups.values()].map(e => { const times = e.times.sort((a, b) => a - b); return { ...e, mean: times.length ? Math.round(times.reduce((a, b) => a + b, 0) / times.length) : null, p95: times.length ? times[Math.ceil(times.length * .95) - 1] : null, csat: e.ratings.length ? (e.ratings.reduce((a, b) => a + b, 0) / e.ratings.length).toFixed(2) : '未评分' } })
})
onMounted(async () => { try { history.value = await learningApi.listExperiments() } catch (e) { error.value = apiError(e) } })
onBeforeUnmount(() => { if (executionTimer) clearInterval(executionTimer) })
function addExpectedEntity() {
  if (expectedEntityInputs.value.length < 40) expectedEntityInputs.value.push('')
}
function removeExpectedEntity(index: number) {
  if (expectedEntityInputs.value.length > 3) expectedEntityInputs.value.splice(index, 1)
}
async function runComparison() {
  if (!question.value.trim() || running.value) return
  const expectedEntities = expectedEntityInputs.value.map(value => value.trim()).filter(Boolean)
  running.value = true; error.value = ''; executionPhase.value = 'running'; executionStartedAt.value = Date.now(); executionElapsed.value = 0
  if (executionTimer) clearInterval(executionTimer)
  executionTimer = setInterval(() => { if (executionStartedAt.value) executionElapsed.value = Math.floor((Date.now() - executionStartedAt.value) / 1000) }, 1000)
  try {
    const saved = await learningApi.runExperiment({ question: question.value.trim(), referenceAnswer: referenceAnswer.value.trim(), expectedEntities, experimentType: experimentType.value, includeAblations: experimentType.value === 'METHODS' && includeAblations.value, taskId: taskId.value }) as Run
    latest.value = saved; history.value = [saved, ...history.value].slice(0, 100)
  } catch (e) { error.value = apiError(e, '实验未完成，请检查 AI 服务和模型配置'); executionPhase.value = 'idle' } finally { running.value = false; if (executionTimer) { clearInterval(executionTimer); executionTimer = null }; if (latest.value) executionPhase.value = 'complete' }
}
async function rate(mode: string, score: number) {
  if (!latest.value || !score) return
  const key = latest.value.results.find(result => result.resultKey === mode || result.mode === mode)?.resultKey || mode
  try { latest.value = await learningApi.rateExperiment(latest.value.id, { [key]: score }); history.value = history.value.map(r => r.id === latest.value?.id ? latest.value! : r) } catch (e) { error.value = apiError(e) }
}
function download(content: string, filename: string, type: string) {
  const url = URL.createObjectURL(new Blob([content], { type }))
  const link = document.createElement('a'); link.href = url; link.download = filename; link.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
async function exportResults() { try { download(JSON.stringify(await learningApi.exportExperimentsJson(), null, 2), 'software-engineering-experiments.json', 'application/json') } catch { download(JSON.stringify(experimentJson(history.value as unknown as ExperimentExportRun[]), null, 2), 'software-engineering-experiments.json', 'application/json') } }
async function exportCsv() { try { const blob = await learningApi.exportExperimentsCsv(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'software-engineering-experiments.csv'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) } catch { download(experimentCsv(history.value as unknown as ExperimentExportRun[]), 'software-engineering-experiments.csv', 'text/csv;charset=utf-8') } }
function score(value?: number) { return value == null ? '未测评' : (value * 100).toFixed(1) + '%' }
</script>
<template>
  <div class="page-stack">
    <SectionHeading eyebrow="研究与评测" title="问答实验" description="同一问题、模型配置和证据集，对照观察三种问答策略。"><div class="experiment-export-actions"><button class="button button-outline" :disabled="!history.length" @click="exportResults"><ArrowDownToLine :size="16" />导出 JSON</button><button class="button button-outline" :disabled="!history.length" @click="exportCsv"><ArrowDownToLine :size="16" />导出 CSV</button></div></SectionHeading>
    <section class="experiment-intro"><span class="experiment-icon"><FlaskConical :size="20" /></span><div><p class="eyebrow">对照实验</p><h2>分别比较问答方法与 Qwen 微调效果</h2><p>方法实验固定默认模型；Qwen 矩阵复用同一次图谱证据，比较基座与 LoRA 在三种策略下的表现。</p></div></section>
    <section class="experiment-modes"><article><span class="mode-index">A</span><strong>大模型直答</strong><p>直接提问，不访问图谱。</p></article><article><span class="mode-index">B</span><strong>三元组 + 大模型</strong><p>使用共享证据，不向提示词注入分数。</p></article><article><span class="mode-index">C</span><strong>排序评分 + 原始提示词</strong><p>使用排序评分证据和原始提示词，先选择直接作答证据，再生成答案。</p></article></section>
    <section class="experiment-run-form"><label for="experiment-type">实验方案</label><select id="experiment-type" v-model="experimentType"><option value="METHODS">方法对照：固定默认模型</option><option value="QWEN_MATRIX">模型对照：Qwen 基座 × LoRA × 三种方法</option></select><p v-if="experimentType === 'QWEN_MATRIX'" class="matrix-notice">此方案只调用本地 Qwen 基座和 LoRA，不调用 DeepSeek/M3E；六种组合共用一次图谱检索，逐项运行。训练标签尚未经教师审校，结果仅作探索性比较。</p><label for="experiment-question">统一测试问题</label><textarea id="experiment-question" v-model="question" maxlength="2000" rows="2"></textarea><label for="reference-answer">参考答案（可选）</label><textarea id="reference-answer" v-model="referenceAnswer" maxlength="4000" rows="2" placeholder="由教师或教材确定；留空时不生成文本相似度指标"></textarea><label>期望答案实体（可选）</label><div class="expected-entity-list"><div v-for="(entity, index) in expectedEntityInputs" :key="index" class="expected-entity-row"><input v-model="expectedEntityInputs[index]" data-testid="expected-entity-input" :aria-label="`期望实体 ${index + 1}`" maxlength="100" placeholder="一个实体或答案短语，可含标点" /><button type="button" class="entity-icon-button" :aria-label="`移除期望实体 ${index + 1}`" title="移除期望实体" :disabled="expectedEntityInputs.length <= 3" @click="removeExpectedEntity(index)"><X :size="15" /></button></div></div><button type="button" class="entity-add-button" aria-label="添加期望实体" :disabled="expectedEntityInputs.length >= 40" @click="addExpectedEntity"><Plus :size="15" />添加实体</button><small>每格内容整体作为一个答案实体或短语，可包含逗号、顿号等标点。本题可将完整目标句填写在一个框中；多个目标请分别填写或添加输入框。答案实体不是三元组的主语、关系、宾语；最多 40 项，空白不参与评分。</small><div class="experiment-actions"><label v-if="experimentType === 'METHODS'" class="ablation-control"><input v-model="includeAblations" type="checkbox" />附加消融实验</label><span v-else class="matrix-run-note">串行运行 6 个条件；RANKED 每个模型均执行证据筛选和答案校验</span><button class="button button-dark" :disabled="running || !question.trim()" @click="runComparison"><Play :size="15" />{{ running ? '矩阵实验运行中…' : '开始对比实验' }}</button></div><small v-if="experimentType === 'METHODS'">各模式使用相同模型与生成参数；排序评分组包含证据选择和生成两次调用，总耗时与 token 按实际记录。失败结果不参与评分，参考答案与期望实体仅用于生成后的评价。</small></section>
    <section class="experiment-execution-status" aria-live="polite"><div><p class="eyebrow">批量执行状态</p><strong>{{ executionStatusText }}</strong></div><div class="execution-status-meta"><span>预期条件 {{ expectedConditions }}</span><span v-if="executionPhase === 'running'">已运行 {{ executionElapsed }} 秒</span><span v-if="latest">实际返回 {{ latest.results.length }} 条</span></div><small v-if="executionPhase === 'running'">失败条件会保留为失败状态，不会生成或参与答案评分。</small></section>
    <div v-if="error" class="inline-notice" role="alert"><CircleHelp :size="16" />{{ error }}</div>
    <section v-if="latest" class="content-section experiment-history"><div class="section-title-row"><div><p class="eyebrow">{{ latest.evaluation?.experimentType === 'QWEN_MATRIX' ? 'Qwen 基座 × LoRA 实验矩阵' : '本次结果' }}</p><h2>{{ latest.question }}</h2></div><span class="history-count"><Timer :size="13" />{{ new Date(latest.createdAt).toLocaleString('zh-CN') }}</span></div><div class="compare-result-grid"><article v-for="result in latest.results" :key="result.resultKey || result.mode" class="compare-result-card" :class="{ 'result-failed': result.error }"><div class="compare-result-title"><strong>{{ modeNames[result.resultKey || result.mode] || result.resultKey || result.mode }}</strong><small>{{ result.error ? '失败' : '成功' }} · {{ result.latencyMs }} ms</small></div><p v-if="result.error" class="compare-error">{{ result.error }}</p><p v-else class="compare-answer">{{ result.answer }}</p><details v-if="result.triples?.length" class="compare-evidence"><summary>{{ result.triples.length }} 条知识证据 · 查看返回顺序</summary><ol><li v-for="triple in result.triples" :key="triple.subject + triple.predicate + triple.object">{{ triple.subject }} — {{ triple.predicate }} — {{ triple.object }}<small v-if="triple.score !== undefined">（{{ Number(triple.score).toFixed(3) }}）</small></li></ol></details><dl v-if="!result.error" class="experiment-scores"><div><dt>ROUGE-L</dt><dd>{{ score(latest.evaluation?.metricsByMode?.[result.resultKey || result.mode]?.rougeL) }}</dd></div><div><dt>BLEU ≤ 4</dt><dd>{{ score(latest.evaluation?.metricsByMode?.[result.resultKey || result.mode]?.bleu4) }}</dd></div><div><dt>有效阶数</dt><dd>{{ latest.evaluation?.metricsByMode?.[result.resultKey || result.mode]?.bleuOrder ?? '—' }}</dd></div><div><dt>实体召回率</dt><dd>{{ score(latest.evaluation?.metricsByMode?.[result.resultKey || result.mode]?.entityRecall) }}</dd></div></dl><label v-if="!result.error" class="rating-select">人工评分<select :value="latest.ratings[result.resultKey || result.mode] || ''" @change="rate(result.resultKey || result.mode, Number(($event.target as HTMLSelectElement).value))"><option value="">选择 1–5 分</option><option v-for="n in 5" :key="n" :value="n">{{ n }} 分</option></select></label><details v-if="result.prompt && result.mode !== 'RANKED'" class="prompt-details"><summary>查看提示词（RANKED 不展示后台约束提示）</summary><pre>{{ result.prompt }}</pre></details><p v-if="result.grounding" class="compare-evidence">已选择 {{ result.grounding.selectedIds.length }} / {{ result.grounding.candidates.length }} 条证据；{{ result.grounding.modelCallCount }} 次模型调用</p><details v-if="result.grounding"><summary>查看证据筛选与校验记录</summary><pre>{{ JSON.stringify(result.grounding, null, 2) }}</pre></details><details v-if="result.provenance"><summary>查看运行配置与证据来源</summary><pre>{{ JSON.stringify({ model: result.provenance.model, temperature: result.provenance.temperature, maxTokens: result.provenance.maxTokens, topK: result.provenance.topK, systemPromptVersion: result.provenance.systemPromptVersion }, null, 2) }}</pre></details></article></div><small class="local-history-note">{{ latest.evaluation?.note || '早期导入记录，未生成可复核的实验指标。自动指标与人工评分分别呈现，不等同于事实正确性。' }}</small></section>
    <section v-if="summary.length" class="content-section"><div class="section-title-row"><h2>个人实验统计</h2><small>方法实验与 Qwen 矩阵分组汇总；不同实验类型不会混算</small></div><div class="table-scroll"><table class="experiment-table"><thead><tr><th>实验条件</th><th>运行数</th><th>错误率</th><th>成功平均耗时</th><th>成功 P95</th><th>人工均分</th></tr></thead><tbody><tr v-for="row in summary" :key="row.key"><td>{{ row.label }}</td><td>{{ row.count }}</td><td>{{ (row.failed * 100 / row.count).toFixed(1) }}%</td><td>{{ row.mean == null ? '未测得' : row.mean + ' ms' }}</td><td>{{ row.p95 == null ? '未测得' : row.p95 + ' ms' }}</td><td>{{ row.csat }}</td></tr></tbody></table></div></section>
    <section class="content-section experiment-history"><div class="section-title-row"><h2>实验历史</h2><span class="history-count">{{ history.length }} 条</span></div><div v-if="history.length" class="saved-experiment-list"><button v-for="run in history" :key="run.id" @click="latest = run"><span>{{ run.question }}</span><small>{{ new Date(run.createdAt).toLocaleString('zh-CN') }}</small></button></div><div v-else class="empty-state compact-empty"><FlaskConical :size="24" /><strong>还没有实验记录</strong><span>运行一次对比，记录会保存到当前账户。</span></div></section>
  </div>
</template>
<style scoped>
.experiment-export-actions{display:flex;gap:8px;flex-wrap:wrap}
.experiment-execution-status{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:14px 16px;background:#f7faf7;border:1px solid var(--border-default);border-radius:var(--radius-md)}.experiment-execution-status .eyebrow{margin:0 0 4px;color:var(--accent)}.experiment-execution-status strong{color:var(--text);font-size:13px}.experiment-execution-status small{width:100%;color:var(--text-muted);font-size:10px}.execution-status-meta{display:flex;flex-wrap:wrap;gap:10px;color:var(--text-muted);font-size:10px}.result-failed{border-color:#edcfc6;background:#fff8f5}.result-failed .compare-result-title small{color:var(--danger)}.compare-evidence summary{display:flex;align-items:center;gap:6px;color:var(--accent);cursor:pointer}.compare-evidence ol{margin:9px 0 0;padding-left:18px;color:var(--text-muted);font-size:10px;line-height:1.7}.compare-evidence li small{color:var(--text-subtle)}
.experiment-run-form>input,.expected-entity-row input{padding:11px 13px;border:1px solid var(--border,#dce5df);border-radius:8px;background:white}.experiment-run-form>label{margin-top:9px}.experiment-run-form>small{line-height:1.7;color:#64756c}.expected-entity-list{display:grid;gap:8px}.expected-entity-row{display:flex;gap:8px}.expected-entity-row input{flex:1;min-width:0}.entity-icon-button,.entity-add-button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid var(--border,#dce5df);border-radius:6px;background:#fff;color:#40574b;cursor:pointer}.entity-icon-button{width:40px;aspect-ratio:1}.entity-icon-button:disabled,.entity-add-button:disabled{opacity:.45;cursor:not-allowed}.entity-add-button{justify-self:start;padding:8px 11px}.experiment-run-form>.experiment-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:9px}.ablation-control{display:flex;gap:8px;align-items:center}.experiment-scores{display:flex;gap:16px;flex-wrap:wrap}.experiment-scores dt{font-size:11px;color:#758079}.experiment-scores dd{margin:5px 0;font-weight:600}.compare-result-card pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:250px;overflow:auto;font-size:12px;background:#f6f8f5;padding:12px}.compare-result-card details{margin-top:12px;font-size:12px}.experiment-table{width:100%;text-align:left;border-collapse:collapse;font-size:13px}.experiment-table th,.experiment-table td{padding:12px 10px;border-bottom:1px solid #e8ede8}.table-scroll{overflow-x:auto}.experiment-table th{white-space:nowrap;color:#64756c}
</style>
